const e = $input.first().json.output;
const chatId = $('When Executed by Another Workflow').first().json.chat_id;

let query, params;

switch (e.tipo_consulta) {
  case 'total_categoria':
    query = `SELECT COALESCE(SUM(g.monto),0) AS total, COUNT(*) AS num
             FROM gastos g JOIN categorias c ON g.categoria_id = c.id
             WHERE g.chat_id = $1 AND c.nombre = $2 AND g.fecha BETWEEN $3 AND $4`;
    params = [chatId, e.categoria, e.fecha_inicio, e.fecha_fin];
    break;
  case 'desglose_categorias':
    query = `SELECT c.nombre, c.emoji, SUM(g.monto) AS total, COUNT(*) AS num
             FROM gastos g JOIN categorias c ON g.categoria_id = c.id
             WHERE g.chat_id = $1 AND g.fecha BETWEEN $2 AND $3
             GROUP BY c.nombre, c.emoji ORDER BY total DESC`;
    params = [chatId, e.fecha_inicio, e.fecha_fin];
    break;
  case 'lista_gastos':
    query = `SELECT g.monto, g.descripcion, g.fecha, c.nombre AS categoria, c.emoji
             FROM gastos g LEFT JOIN categorias c ON g.categoria_id = c.id
             WHERE g.chat_id = $1
             ORDER BY g.fecha DESC, g.id DESC LIMIT $2`;
    params = [chatId, e.limite || 10];
    break;
  default: // total_periodo
    query = `SELECT COALESCE(SUM(monto),0) AS total, COUNT(*) AS num
             FROM gastos WHERE chat_id = $1 AND fecha BETWEEN $2 AND $3`;
    params = [chatId, e.fecha_inicio, e.fecha_fin];
}

return [{ json: { query, params } }];
